import{_ as e,o as s,c as t,a2 as d}from"./chunks/framework.DoCD98hS.js";const k=JSON.parse('{"title":"文档与服务","description":"","frontmatter":{},"headers":[],"relativePath":"modules/docs-and-services.md","filePath":"modules/docs-and-services.md","lastUpdated":1795138584000}'),i={name:"modules/docs-and-services.md"};function o(l,a,n,c,p,h){return s(),t("div",null,[...a[0]||(a[0]=[d(`<h1 id="文档与服务" tabindex="-1">文档与服务 <a class="header-anchor" href="#文档与服务" aria-label="Permalink to &quot;文档与服务&quot;">​</a></h1><table tabindex="0"><thead><tr><th>模块（包名前缀均为 <code>@melt-js/</code>）</th><th>职责</th></tr></thead><tbody><tr><td><code>docs-all</code></td><td>全仓库统一入口，介绍模块、加载策略与核心分层。</td></tr><tr><td><code>docs-bag</code></td><td>Bag 插件化后台的详细文档：宿主、请求、权限、官方插件与插件开发。</td></tr></tbody></table><p>本站只收录对外公开的模块；配套服务等非公开交付不在 <code>docs-all</code> 展开，由对应包自身文档维护。</p><h2 id="两个文档站的边界" tabindex="-1">两个文档站的边界 <a class="header-anchor" href="#两个文档站的边界" aria-label="Permalink to &quot;两个文档站的边界&quot;">​</a></h2><ul><li><code>docs-all</code> 负责全局入口，先简要介绍每个模块以及统一接入方向。</li><li><code>docs-bag</code> 保留 Bag 的深入使用手册，不复制一份详细专题到新站。</li></ul><p>在仓库根目录运行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 统一文档：开发 40030 / 预览 40040</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:dev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:build</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> docs:preview</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Bag 专题：开发 40010 / 预览 40020</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pnpm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bag:docs:dev</span></span></code></pre></div><p>两个站独立构建和部署；尚未约定线上专题地址，因此这里不硬编码跨站域名。Bag 配套服务的配置与部署说明由该服务包自身文档维护。</p><h2 id="托管方式-github-对外-sftp-联调" tabindex="-1">托管方式：GitHub 对外，SFTP 联调 <a class="header-anchor" href="#托管方式-github-对外-sftp-联调" aria-label="Permalink to &quot;托管方式：GitHub 对外，SFTP 联调&quot;">​</a></h2><p>远程组件包可以走两种静态托管，产物内容一致，差别只在元信息里的地址形态：</p><table tabindex="0"><thead><tr><th>目标</th><th>地址形态</th><th>定位</th></tr></thead><tbody><tr><td>GitHub Pages</td><td><code>hel-meta.json</code> 里的资源地址是相对路径（<code>HEL_RELATIVE_PATH_GITHUB=1</code>），不含站点域名</td><td>对外标准分发</td></tr><tr><td>SFTP</td><td>资源地址写成绝对 URL（<code>HEL_RELATIVE_PATH_SFTP=0</code>）</td><td>实时发布、联调验证</td></tr></tbody></table><p>GitHub 之所以是对外标准，关键在「元信息不带域名前缀」：使用者把产物下载后放进自己项目的 <code>public/</code> 目录，或用任意静态服务器托管，<code>hel-meta.json</code> 不用改任何一行就能继续当远程组件源。换成 SFTP 那种写死域名的形态，别人一挪位置就得改元信息，等于把托管地址绑死在作者服务器上。</p><p>SFTP 的定位是测试通道：绝对地址让产物上传即可被宿主直接引用，不需要推断路径，改完立刻能验。它适合内部联调，不适合当对外分发地址。</p><p>发布地址调整时同步检查 <code>HEL_RELATIVE_PATH_GITHUB</code> / <code>HEL_RELATIVE_PATH_SFTP</code>：不要把带域名的元信息发到 GitHub，也不要把相对路径带到需要跨域直连的联调入口。</p><h2 id="收录边界" tabindex="-1">收录边界 <a class="header-anchor" href="#收录边界" aria-label="Permalink to &quot;收录边界&quot;">​</a></h2><p><code>docs-all</code> 是公开文档站，只写 <code>private: false</code> 且已经或准备对外发布的包。<code>private: true</code> 的包（含内部服务、未发布实验包、企业内部项目）不出现在任何页面：包名、目录名、索引行、能力表、演示链接、启动命令和端口都不写。这类内容留在包内 README 或私有文档站，不回流到本站。</p>`,16)])])}const b=e(i,[["render",o]]);export{k as __pageData,b as default};
